class Solution:
    def maxCompatibilitySum(self, students: List[List[int]], mentors: List[List[int]]) -> int:
        m = len(students)
        score = [[sum(a == b for a, b in zip(s, t)) for t in mentors] for s in students]
        used = [False] * m

        def dfs(i):
            if i == m:
                return 0
            best = 0
            for j in range(m):
                if not used[j]:
                    used[j] = True
                    best = max(best, score[i][j] + dfs(i + 1))
                    used[j] = False
            return best

        return dfs(0)

