class Solution {
public:
    int m;
    vector<vector<int>> score;

    int dfs(int i, int usedMask) {
        if (i == m) return 0;
        int best = 0;
        for (int j = 0; j < m; j++) {
            if (!(usedMask >> j & 1)) {
                best = max(best, score[i][j] + dfs(i + 1, usedMask | (1 << j)));
            }
        }
        return best;
    }

    int maxCompatibilitySum(vector<vector<int>>& students, vector<vector<int>>& mentors) {
        m = students.size();
        int n = students[0].size();
        score.assign(m, vector<int>(m));
        for (int i = 0; i < m; i++)
            for (int j = 0; j < m; j++)
                for (int k = 0; k < n; k++)
                    score[i][j] += students[i][k] == mentors[j][k];
        return dfs(0, 0);
    }
};

