class Solution {
    private int m;
    private int[][] score;

    public int maxCompatibilitySum(int[][] students, int[][] mentors) {
        m = students.length;
        int n = students[0].length;
        score = new int[m][m];
        for (int i = 0; i < m; i++)
            for (int j = 0; j < m; j++)
                for (int k = 0; k < n; k++)
                    score[i][j] += students[i][k] == mentors[j][k] ? 1 : 0;
        return dfs(0, 0);
    }

    private int dfs(int i, int usedMask) {
        if (i == m) return 0;
        int best = 0;
        for (int j = 0; j < m; j++) {
            if ((usedMask & (1 << j)) == 0) {
                best = Math.max(best, score[i][j] + dfs(i + 1, usedMask | (1 << j)));
            }
        }
        return best;
    }
}

