        s.reduce((acc, v, k) => acc + (v === t[k] ? 1 : 0), 0)));
    const used = new Array(m).fill(false);
    const dfs = function(i) {
        if (i === m) return 0;
        let best = 0;
        for (let j = 0; j < m; j++) {
            if (!used[j]) {
                used[j] = true;
                best = Math.max(best, score[i][j] + dfs(i + 1));
                used[j] = false;
            }
        }
        return best;
    };
    return dfs(0);
};

