            int i = Integer.bitCount(mask) - 1;
            for (int j = 0; j < m; j++) {
                if ((mask & (1 << j)) != 0) {
                    dp[mask] = Math.max(dp[mask], dp[mask ^ (1 << j)] + score[i][j]);
                }
            }
        }
        return dp[(1 << m) - 1];
